/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
class GUPMCRCustCategoryHierarchyLookup
{
    public  boolean returnRefRecID = false;

}

Method.Source:
final public boolean parmreturnRefRecID(boolean _returnRefRecID = returnRefRecID)
{
    returnRefRecID = _returnRefRecID;

    return returnRefRecID;
}

public MCRCustCategoryHierarchy performLookup(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(GUPMCRCustCategoryHierarchyLookup));
    args.caller(this);

    args.parmObject(this);
    args.lookupField(fieldNum(MCRCustCategoryHierarchy, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
    MCRCustCategoryHierarchy custCategoryHierarchy = formRun.selectRecordModeSelectedRecord() as MCRCustCategoryHierarchy;

    return custCategoryHierarchy;
}

public static GUPMCRCustCategoryHierarchyLookup construct(boolean _returnRefRecID)
{
    return new GUPMCRCustCategoryHierarchyLookup(_returnRefRecID);
}
